python3 << 'EOF'
import openpyxl
from collections import defaultdict, Counter
import datetime, re

wb = openpyxl.load_workbook('/sessions/fervent-busy-ritchie/mnt/uploads/OTG Oppr.xlsx')
ws = wb.active
rows = list(ws.iter_rows(values_only=True))
data = rows[1:]
open_gigs = [r for r in data if r[19] == 'Open']
today = datetime.datetime(2026, 6, 9)

def check_ingestion(r):
    issues = []
    if not r[9] or r[9].strip() == '':           issues.append('LocationName')
    if not r[11] or r[11].strip() == '':          issues.append('TimeCommitment')
    if not r[12]:                                  issues.append('GigStart')
    if not r[13]:                                  issues.append('GigEnd')
    if not r[7] or r[7].strip() == '':            issues.append('Function')
    if not r[6] or r[6].strip() == '':            issues.append('BusinessUnit')
    if r[1] and not r[1].strip().startswith('['): issues.append('TypeTag')
    return issues

# Distribution of how many fields missing per blocked gig
field_count_dist = Counter()
for r in open_gigs:
    issues = check_ingestion(r)
    if issues:
        field_count_dist[len(issues)] += 1

print("Blocked gigs by number of missing fields:")
for k in sorted(field_count_dist):
    print(f"  {k} field(s) missing: {field_count_dist[k]} gigs")

# Agency-level: which agencies have ANY passing gigs (to show contrast)
agency_blocked = defaultdict(lambda: {'total':0,'blocked':0,'passing':0})
for r in open_gigs:
    agency = r[9] or 'Unknown'
    agency_blocked[agency]['total'] += 1
    iss = check_ingestion(r)
    if iss:
        agency_blocked[agency]['blocked'] += 1
    else:
        agency_blocked[agency]['passing'] += 1

print("\nAgencies with most PASSING gigs:")
ranked_pass = sorted(agency_blocked.items(), key=lambda x: -x[1]['passing'])
for agency, d in ranked_pass[:10]:
    print(f"  {agency[:50]:50} passing={d['passing']}/{d['total']}")

# What % of the 633 open gigs would be visible on OTEP?
total_passing = sum(d['passing'] for d in agency_blocked.values())
print(f"\nTotal passing (visible on OTEP): {total_passing} / {len(open_gigs)} = {total_passing/len(open_gigs)*100:.1f}%")
EOF

